// Prepare Today's 2 Video Slots (13:30 Daytime and 18:30 Evening Peak)
const inputRows = $input.all().map(i => i.json).filter(r => r.Topic_FI || r.topic);

// Fallback sample topics if sheet is empty or being initialized
const defaultTopics = [
  {
    Day: 1,
    Slot: 1,
    Publish_Time: "13:30",
    Topic_FI: "Miksi aivosi kaipaavat kaaosta? (Dopamiiniloukku)",
    English_Meaning: "Why your brain craves chaos",
    Primary_Keyword_FI: "dopamiinivaje",
    Secondary_SEO_Tags: "mieli, psykologia, aivot, dopamiini, shorts",
    CTA_Keyword: "DOPAMIINI",
    Category: "Aivot & Dopamiini"
  },
  {
    Day: 1,
    Slot: 2,
    Publish_Time: "18:30",
    Topic_FI: "Lopeta yliajattelu 10 sekunnissa: Aivojesi sammutusnappi",
    English_Meaning: "Stop overthinking in 10 seconds",
    Primary_Keyword_FI: "mielenrauha",
    Secondary_SEO_Tags: "yliajattelu, ahdistus, rauha, stoalaisuus, shorts",
    CTA_Keyword: "STOP",
    Category: "Mielenrauha & Stressi"
  }
];

const rowsToUse = inputRows.length >= 2 ? inputRows.slice(0, 2) : (inputRows.length === 1 ? [inputRows[0], defaultTopics[1]] : defaultTopics);

// Calculate YouTube RFC 3339 UTC schedule timestamps for Europe/Helsinki
function getHelsinkiUtcIso(timeStr) {
  const now = new Date();
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Helsinki', timeZoneName: 'shortOffset' });
  const parts = dtf.formatToParts(now);
  const tzPart = parts.find(p => p.type === 'timeZoneName').value; // e.g. 'GMT+3' or 'GMT+2'
  const offsetHours = parseInt(tzPart.replace('GMT', '') || '+3', 10);

  const [h, m] = timeStr.split(':').map(Number);
  const todayYMD = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Helsinki' }).format(now);
  const [year, month, day] = todayYMD.split('-').map(Number);

  return new Date(Date.UTC(year, month - 1, day, h - offsetHours, m, 0)).toISOString();
}

return rowsToUse.map((row, index) => {
  const slot = index === 0 ? 1 : 2;
  const targetTime = slot === 1 ? "13:30" : "18:30";
  const publishAtIso = getHelsinkiUtcIso(targetTime);

  return {
    json: {
      day: row.Day || 1,
      slot: slot,
      publish_time: targetTime,
      publishAt_iso: publishAtIso,
      topic: row.Topic_FI || row.topic,
      english_meaning: row.English_Meaning || "",
      primary_keyword: row.Primary_Keyword_FI || "psykologia",
      secondary_seo_tags: row.Secondary_SEO_Tags || "mielen voima, psykologia, elämäntapamuutos, shorts",
      cta_keyword: row.CTA_Keyword || (slot === 1 ? "DOPAMIINI" : "RAUHA"),
      category: row.Category || "Psykologia",
      sheet_row_id: row.row_number || row.ID || null
    }
  };
});

