const slotContext = $('🔄 Loop Over 2 Slots (Sequential Batch)').first().json;

const REQUIRED_PREFIX = "Minimalist flat 2D vector stickman, extreme 9:16 vertical orientation, pure #FFFFFF white background, high-contrast black line art";
const MAX_TOTAL_WORDS = 230; // hard cap — keeps spoken runtime safely under the 180s Shorts ceiling

let parsed;
try {
  const responseText = $input.first().json.candidates[0].content.parts[0].text;
  parsed = JSON.parse(responseText);
} catch (err) {
  throw new Error(`Mielen Voima: Gemini returned unparseable output for topic "${slotContext.topic}" — ${err.message}`);
}

if (!Array.isArray(parsed.scenes) || parsed.scenes.length < 5) {
  throw new Error(`Mielen Voima: Script for "${slotContext.topic}" returned ${parsed.scenes ? parsed.scenes.length : 0} scenes — fewer than the minimum 5 required.`);
}

const cleanScenes = parsed.scenes.map((s, idx) => {
  let imagePrompt = String(s.image_prompt || '').trim();
  if (!imagePrompt.startsWith(REQUIRED_PREFIX)) {
    imagePrompt = `${REQUIRED_PREFIX}, ${imagePrompt}`;
  }
  return {
    scene_id: idx + 1,
    voiceover: String(s.voiceover || '').trim(),
    image_prompt: imagePrompt,
    keyword: String(s.keyword || slotContext.cta_keyword).trim().toUpperCase()
  };
});

const totalWords = cleanScenes.reduce((sum, s) => sum + s.voiceover.split(/\s+/).filter(Boolean).length, 0);
if (totalWords > MAX_TOTAL_WORDS) {
  throw new Error(`Mielen Voima: Script for "${slotContext.topic}" is ${totalWords} words — over the ${MAX_TOTAL_WORDS}-word safety cap. Regenerate with a tighter prompt rather than risk exceeding the 180s Shorts limit.`);
}

return {
  ...slotContext,
  title: parsed.title || `${slotContext.topic} #shorts #mielenvoima`,
  description: parsed.description || `Tilaa @Mielen_Voima saadaksesi lisää oivalluksia. #shorts #mielenvoima`,
  render_payload: {
    topic: slotContext.topic,
    video_id: `mv_d${slotContext.day}_s${slotContext.slot}_${Date.now()}`,
    voice: "fi-FI-HarriNeural",
    scenes: cleanScenes
  }
};

const staticData = $getWorkflowStaticData('global');
staticData.pollAttempts = (staticData.pollAttempts || 0) + 1;

const MAX_POLL_ATTEMPTS = 20; // 20 x 25s ~= 8 min after the initial 75s wait
const response = $input.first().json;

let outcome;
if (response.status === 'completed') {
  outcome = 'completed';
} else if (response.status === 'failed') {
  outcome = 'failed';
} else if (staticData.pollAttempts >= MAX_POLL_ATTEMPTS) {
  outcome = 'timeout';
} else {
  outcome = 'retry';
}

return {
  json: {
    ...response,
    pollAttempt: staticData.pollAttempts,
    outcome
  }
};

